spring:
  application:
    name: sofascore-local-lab
  config:
    import: "optional:file:.env[.properties]"
  profiles:
    default: local
  threads:
    virtual:
      enabled: true
  datasource:
    url: jdbc:postgresql://127.0.0.1:${POSTGRES_PORT:5432}/${POSTGRES_DB:sofascore_local_lab}
    username: ${POSTGRES_USER:sofascore_lab}
    password: ${POSTGRES_PASSWORD:}
    hikari:
      maximum-pool-size: 4
      minimum-idle: 1
      connection-timeout: 5000
      validation-timeout: 2000
  jpa:
    open-in-view: false
    hibernate:
      ddl-auto: none
    properties:
      hibernate:
        jdbc:
          time_zone: UTC
  flyway:
    enabled: true
    validate-migration-naming: true
  cache:
    type: caffeine
    cache-names:
      - endpointCatalog
      - providerResponses
    caffeine:
      spec: maximumSize=500,expireAfterWrite=30m
  thymeleaf:
    cache: true
  servlet:
    multipart:
      max-file-size: 6MB
      max-request-size: 32MB
      file-size-threshold: 32MB

server:
  address: 127.0.0.1
  port: 8087
  shutdown: graceful
  tomcat:
    max-part-count: 82
  servlet:
    session:
      cookie:
        http-only: true
        same-site: strict
  error:
    include-message: never
    include-stacktrace: never

management:
  endpoints:
    web:
      exposure:
        include: health,info,metrics
  endpoint:
    health:
      show-details: always
  info:
    env:
      enabled: true

info:
  app:
    name: SofaScore Local Lab
    version: 0.1.0-rc.1-SNAPSHOT
    phase: J8-BENCHMARK-VALIDATED
    status: EXPERIMENTAL_LOCAL_ONLY

