214:                 d.headersReceivedAt()==null?clock.instant():d.headersReceivedAt(),d.retryAfterNotBefore());
215:         if(observed.compareAndSet(null,evidence)) persistRefusal(evidence);
216:     }
217:     /** Authenticated worker evidence is accepted only for explicitly qualified profiles. */
218:     private void recordAuthenticatedDeparture(UUID dispatchId, DepartureProfile profile,
219:                                              Instant requestedAt, Instant observedAt) {
220:         if ((profile != DepartureProfile.LIVE_V8 && profile != DepartureProfile.LIVE_V10) || requestedAt == null) return;
221:         if (observedAt == null || requestedAt.isAfter(observedAt))
222:             throw new IllegalStateException("PROVIDER_REQUESTED_TIMESTAMP_INCOHERENT");
223:         if (profile == DepartureProfile.LIVE_V10) store.recordAuthenticatedV10Departure(dispatchId,requestedAt,observedAt);
224:         else store.recordAuthenticatedV8Departure(dispatchId,requestedAt,observedAt);
225:     }
226:     private void persistRefusal(Refusal refusal) {
227:         pendingRefusal.compareAndSet(null,refusal);
228:         store.suspend(refusal.evidenceId(),refusal.campaignId(),refusal.status(),refusal.at(),refusal.retryAt());
229:         pendingRefusal.compareAndSet(refusal,null);
230:     }
231:     private void flushPendingRefusal() {
232:         Refusal pending=pendingRefusal.get();
233:         if(pending!=null) persistRefusal(pending);
234:     }
